export declare const APPLY_GIFT_CARD_ON_CART_MUTATION = "\n  mutation APPLY_GIFT_CARD_ON_CART_MUTATION(\n      $cartId: String!, \n      $giftCardCode: String!,\n      $pageSize: Int! = 100,\n      $currentPage: Int! = 1,\n      $itemsSortInput: QuoteItemsSortInput! = {field: CREATED_AT, order: DESC}\n  ) {\n applyGiftCardToCart(\n    input: {\n     cart_id: $cartId\n     gift_card_code: $giftCardCode\n    }\n  ) {\n    cart {\n      ...CART_FRAGMENT\n    }\n  }\n}\n\n  fragment CART_FRAGMENT on Cart {\n    id\n    total_quantity\n    is_virtual\n    applied_gift_cards {\n      ...APPLIED_GIFT_CARDS_FRAGMENT\n    }\n    gift_receipt_included\n    printed_card_included\n    gift_message {\n      ...GIFT_MESSAGE_FRAGMENT\n    }\n    gift_wrapping {\n      ...GIFT_WRAPPING_FRAGMENT\n    }\n    available_gift_wrappings {\n      ...AVAILABLE_GIFT_WRAPPING_FRAGMENT\n    }\n    prices {\n      gift_options {\n        gift_wrapping_for_items {\n          currency\n          value\n        }\n        gift_wrapping_for_items_incl_tax {\n          currency\n          value\n        }\n        gift_wrapping_for_order {\n          currency\n          value\n        }\n        gift_wrapping_for_order_incl_tax {\n          currency\n          value\n        }\n        printed_card {\n          currency\n          value\n        }\n        printed_card_incl_tax {\n          currency\n          value\n        }\n      }\n      subtotal_with_discount_excluding_tax {\n        currency\n        value\n      }\n      subtotal_including_tax {\n        currency\n        value\n      }\n      subtotal_excluding_tax {\n        currency\n        value\n      }\n      grand_total {\n        currency\n        value\n      }\n      grand_total_excluding_tax {\n        currency\n        value\n      }\n      applied_taxes {\n        label\n        amount {\n          value\n          currency\n        }\n      }\n      discounts {\n        amount {\n          value\n          currency\n        }\n        label\n        coupon {\n          code\n        }\n        applied_to\n      }\n    }\n    applied_coupons {\n      code\n    }\n    itemsV2(\n      pageSize: $pageSize\n      currentPage: $currentPage\n      sort: $itemsSortInput\n    ) {\n      items {\n        ...CART_ITEM_FRAGMENT\n      }\n    }\n    shipping_addresses {\n      country {\n        code\n      }\n      region {\n        code\n      }\n      postcode\n    }\n  }\n\n  \n  fragment CART_ITEM_FRAGMENT on CartItemInterface {\n    __typename\n    uid\n    quantity\n    is_available\n    not_available_message\n    errors {\n      code\n      message\n    }\n\n    prices {\n      price {\n        value\n        currency\n      }\n      discounts {\n        amount {\n          value\n          currency\n        }\n        label\n      }\n      total_item_discount {\n        value\n        currency\n      }\n      row_total {\n        value\n        currency\n      }\n      row_total_including_tax {\n        value\n        currency\n      }\n      price_including_tax {\n        value\n        currency\n      }\n      fixed_product_taxes {\n        amount {\n          value\n          currency\n        }\n        label\n      }\n      original_item_price {\n        value\n        currency\n      }\n      original_row_total {\n        value\n        currency\n      }\n    }\n\n    product {\n      name\n      sku\n      price_tiers {\n        quantity\n        final_price {\n          value\n        }\n        discount {\n          amount_off\n          percent_off\n        }\n      }\n      quantity\n      gift_message_available\n      gift_wrapping_available\n      gift_wrapping_price {\n        currency\n        value\n      }\n      thumbnail {\n        url\n        label\n      }\n      url_key\n      canonical_url\n      categories {\n        url_path\n        url_key\n        name\n      }\n      custom_attributesV2(filters: { is_visible_on_front: true }) {\n        items {\n          code\n          ... on AttributeValue {\n            value\n          }\n          ... on AttributeSelectedOptions {\n            selected_options {\n              value\n              label\n            }\n          }\n        }\n      }\n      only_x_left_in_stock\n      stock_status\n      price_range {\n        ...PRICE_RANGE_FRAGMENT\n      }\n    }\n    ... on SimpleCartItem {\n      available_gift_wrapping {\n        ...AVAILABLE_GIFT_WRAPPING_FRAGMENT\n      }\n      gift_message {\n        ...GIFT_MESSAGE_FRAGMENT\n      }\n      gift_wrapping {\n        ...GIFT_WRAPPING_FRAGMENT\n      }\n      customizable_options {\n        ...CUSTOMIZABLE_OPTIONS_FRAGMENT\n      }\n    }\n    ... on ConfigurableCartItem {\n      available_gift_wrapping {\n        ...AVAILABLE_GIFT_WRAPPING_FRAGMENT\n      }\n      gift_message {\n        ...GIFT_MESSAGE_FRAGMENT\n      }\n      gift_wrapping {\n        ...GIFT_WRAPPING_FRAGMENT\n      }\n      configurable_options {\n        configurable_product_option_uid\n        option_label\n        value_label\n        configurable_product_option_value_uid\n      }\n      configured_variant {\n        uid\n        sku\n        only_x_left_in_stock\n        stock_status\n        thumbnail {\n          label\n          url\n        }\n        price_range {\n          ...PRICE_RANGE_FRAGMENT\n        }\n        price_tiers {\n          quantity\n          final_price {\n            value\n          }\n          discount {\n            amount_off\n            percent_off\n          }\n        }\n      }\n      customizable_options {\n        ...CUSTOMIZABLE_OPTIONS_FRAGMENT\n      }\n    }\n    ...DOWNLOADABLE_CART_ITEMS_FRAGMENT\n    ... on BundleCartItem {\n      available_gift_wrapping {\n        ...AVAILABLE_GIFT_WRAPPING_FRAGMENT\n      }\n      gift_message {\n        ...GIFT_MESSAGE_FRAGMENT\n      }\n      gift_wrapping {\n        ...GIFT_WRAPPING_FRAGMENT\n      }\n      bundle_options {\n        uid\n        label\n        values {\n          uid\n          label\n        }\n      }\n    }\n    ... on GiftCardCartItem {\n      message\n      recipient_email\n      recipient_name\n      sender_email\n      sender_name\n      amount {\n        currency\n        value\n      }\n      is_available\n    }\n  }\n\n  \n  fragment PRICE_RANGE_FRAGMENT on PriceRange {\n    minimum_price {\n      regular_price {\n        value\n        currency\n      }\n      final_price {\n        value\n        currency\n      }\n      discount {\n        percent_off\n        amount_off\n      }\n    }\n    maximum_price {\n      regular_price {\n        value\n        currency\n      }\n      final_price {\n        value\n        currency\n      }\n      discount {\n        percent_off\n        amount_off\n      }\n    }\n  }\n\n  \n  fragment CUSTOMIZABLE_OPTIONS_FRAGMENT on SelectedCustomizableOption {\n    type\n    customizable_option_uid\n    label\n    is_required\n    values {\n      label\n      value\n      price {\n        type\n        units\n        value\n      }\n    }\n  }\n\n  \n  fragment DOWNLOADABLE_CART_ITEMS_FRAGMENT on DownloadableCartItem {\n    links {\n      sort_order\n      title\n    }\n    customizable_options {\n      ...CUSTOMIZABLE_OPTIONS_FRAGMENT\n    }\n  }\n\n  \n  fragment GIFT_WRAPPING_FRAGMENT on GiftWrapping {\n    __typename\n    uid\n    design\n    image {\n      url\n    }\n    price {\n      value\n      currency\n    }\n  }\n\n  \n  fragment GIFT_MESSAGE_FRAGMENT on GiftMessage {\n    __typename\n    from\n    to\n    message\n  }\n\n  \n  fragment AVAILABLE_GIFT_WRAPPING_FRAGMENT on GiftWrapping {\n   __typename\n   uid\n   design\n   image {\n     url\n     label\n   }\n   price {\n     currency\n     value\n   }\n  }\n\n\n  \n  fragment APPLIED_GIFT_CARDS_FRAGMENT on AppliedGiftCard {\n    __typename\n    code\n    applied_balance {\n      value\n      currency\n    }\n    current_balance {\n      value\n      currency\n    }\n    expiration_date\n  }\n\n\n";
